function makeTheIntegerZero(num1, num2) {
  // Try each count k and build k powers of two summing to num1 - k * num2:
  // begin with the binary digits, then split big powers in half until there are k pieces.
  for (let k = 1; k <= 100; k++) {
    const target = num1 - k * num2;
    if (target <= 0) continue;
    const counts = [];
    for (let rest = target; rest > 0; rest = Math.floor(rest / 2)) counts.push(rest % 2);
    let pieces = counts.reduce((a, b) => a + b, 0);
    let e = counts.length - 1;
    while (pieces < k && e >= 1) {
      if (counts[e] === 0) { e--; continue; }
      counts[e]--;
      counts[e - 1] += 2;
      pieces++;
    }
    if (pieces === k) return k;
  }
  return -1;
}

