  if (size === 'large') {
    const num1 = int(1, 1000000000);
    const r = rand();
    if (r < 0.35) return [num1, int(-1000000000, 1000000000)];
    if (r < 0.7) return [num1, int(-1000000000, 0)];
    return [num1, int(0, Math.max(0, Math.floor(num1 / int(1, 40))))];
  }
  const r = rand();
  if (r < 0.1) return [int(1, 1000000000), int(-1000000000, 1000000000)];
